def solve(grid, start, goal):
    from collections import deque

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])

    # Convert grid to a 2D list for easier access
    grid = [list(row) for row in grid]

    # Check if start or goal is out of bounds or is a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[goal[0]][goal[1]] == '#':
        return []

    # Hill Climbing implementation
    def hill_climb():
        path = [start]
        current = start
        while True:
            # Find the best neighbor (closer to the goal)
            best = None
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                    dist = abs(r - goal[0]) + abs(c - goal[1])
                    if best is None or dist < abs(best[0] - goal[0]) + abs(best[1] - goal[1]):
                        best = (r, c)
            # If no better move, we are stuck or reached the goal
            if best is None or best == current:
                break
            path.append(best)
            current = best
            if current == goal:
                return path
        return []

    # Try hill climbing from start
    path = hill_climb()
    if path and path[-1] == goal:
        return path

    # If Hill Climbing failed, use BFS to find a path
    def bfs():
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque([(start, [start])])
        visited[start[0]][start[1]] = True

        while queue:
            current, path = queue.popleft()
            if current == goal:
                return path
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and not visited[r][c]:
                    visited[r][c] = True
                    queue.append(( (r, c), path + [(r, c)] ))
        return []

    return bfs()
```

