def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    # Hill Climbing
    path = [start]
    current = start
    visited = set()
    visited.add(start)

    while True:
        neighbors = get_neighbors(current[0], current[1])
        if not neighbors:
            break  # No more moves, path ends here

        # Choose the neighbor with the lowest heuristic
        best_neighbor = min(neighbors, key=lambda pos: heuristic(pos[0], pos[1]))
        if best_neighbor == goal:
            path.append(goal)
            break
        if best_neighbor in visited:
            break  # Avoid cycles and local optima
        visited.add(best_neighbor)
        path.append(best_neighbor)
        current = best_neighbor

    # Check if reached the goal
    if path[-1] == goal:
        return path
    else:
        return []
