from collections import deque

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    # Bidirectional BFS setup
    start_queue = deque([start])
    goal_queue = deque([goal])

    start_visited = {start}
    goal_visited = {goal}

    # To track the path
    start_to_path = {start: []}
    goal_to_path = {goal: []}

    while start_queue and goal_queue:
        # Expand from start
        if len(start_queue) <= len(goal_queue):
            start_pos = start_queue.popleft()
            for dr, dc in directions:
                r, c = start_pos[0] + dr, start_pos[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in start_visited:
                    start_visited.add((r, c))
                    start_queue.append((r, c))
                    start_to_path[(r, c)] = start_to_path[start_pos] + [start_pos]
        else:
            # Expand from goal
            goal_pos = goal_queue.popleft()
            for dr, dc in directions:
                r, c = goal_pos[0] + dr, goal_pos[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in goal_visited:
                    goal_visited.add((r, c))
                    goal_queue.append((r, c))
                    goal_to_path[(r, c)] = goal_to_path[goal_pos] + [goal_pos]

        # Check for intersection
        if start_visited & goal_visited:
            # Found a common cell
            common = (start_visited & goal_visited).pop()
            # Reconstruct the path
            path_from_start = start_to_path[common] + [common]
            path_from_goal = goal_to_path[common] + [common]
            full_path = path_from_start + path_from_goal[::-1][:-1]
            return full_path

    return []  # No path found
