def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    # Heuristic: Manhattan distance
    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    # Hill Climbing algorithm
    path = [start]
    current = start
    while True:
        if current == goal:
            return path
        neighbors = get_neighbors(current[0], current[1])
        if not neighbors:
            return []
        # Choose the neighbor with the lowest heuristic value
        next_cell = min(neighbors, key=lambda cell: heuristic(cell[0], cell[1]))
        if heuristic(next_cell[0], next_cell[1]) >= heuristic(current[0], current[1]):
            # No improvement, goal is unreachable
            return []
        path.append(next_cell)
        current = next_cell
