def solve(grid, start, goal):
    from collections import defaultdict, deque

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    # Convert grid to adjacency list
    adj = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        adj[(r, c)].append((nr, nc))

    # Hierholzer's Algorithm to find a path from start to goal
    def hierholzer(start, goal):
        stack = [start]
        path = []
        while stack:
            current = stack[-1]
            if current in adj and adj[current]:
                next_node = adj[current].pop()
                stack.append(next_node)
            else:
                path.append(stack.pop())
        # Reverse to get the correct order
        path = path[::-1]
        # Extract the path from start to goal
        path = [p for p in path if p == start or p == goal]
        if not path or path[-1] != goal:
            return []
        return path

    # Try to find a path from start to goal
    path = hierholzer(start, goal)
    if path and path[-1] == goal:
        return path
    return []
