import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Heuristic function: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u, t):
        return abs(u - t)

    # A* algorithm
    pq = [(0 + heuristic(s, t), 0, s)]  # (priority, cost, node)
    visited = [False] * n
    dist = [float('inf')] * n
    dist[s] = 0

    while pq:
        _, cost, u = heapq.heappop(pq)
        if u == t:
            return cost
        if visited[u]:
            continue
        visited[u] = True

        for v, w in graph[u]:
            if dist[v] > cost + w:
                dist[v] = cost + w
                heapq.heappush(pq, (dist[v] + heuristic(v, t), dist[v], v))

    return -1
```

