def solve(n, edges, s, t):
    # Build adjacency list
    from collections import defaultdict, deque

    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v, w in edges:
        graph[u].append((v, w))
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If the topological sort does not include all nodes, the graph has a cycle
    if len(topo_order) != n:
        return -1

    # Relax edges in topological order using Bellman-Ford approach
    dist = [float('inf')] * n
    dist[s] = 0

    for u in topo_order:
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    return dist[t] if dist[t] != float('inf') else -1
