    # Bellman-Ford setup for modified graph with super source
    bellman_ford_adj = [[] for _ in range(n + 1)]
    for u, v, w in edges + super_edges:
        bellman_ford_adj[u].append((v, w))

    h = [float('inf')] * (n + 1)
    h[super_source] = 0

    # Relax edges up to n times
    for i in range(n):
        for u in range(n + 1):
            for v, w in bellman_ford_adj[u]:
                if h[v] > h[u] + w:
                    h[v] = h[u] + w

    # Step 4: Re-weight the edges using h
    reweighted_edges = []
    for u, v, w in edges:
        new_w = w + h[u] - h[v]
        reweighted_edges.append((u, v, new_w))

    # Step 5: Run Dijkstra's algorithm on the reweighted graph
    # Only run Dijkstra's if h[v] is not infinity (i.e., v is reachable from super source)
    # But since we added a super source connected to all nodes with weight 0, all nodes are reachable
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in reweighted_edges:
            if u == v:
                continue  # Skip self loops
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    if dist[t] == float('inf'):
        return -1
    else:
        # Reconstruct the original weight using h
        return dist[t] - h[s] + h[t]
