import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Priority queue for A* search: (priority, node, path_length)
    # Heuristic: Manhattan distance
    def heuristic(node):
        return abs(node - t)

    # Priority queue
    pq = [(heuristic(s), s, 0)]
    visited = [float('inf')] * n
    visited[s] = 0

    while pq:
        _, current, cost = heapq.heuristics(pq)
        if current == t:
            return cost
        if cost > visited[current]:
            continue
        for neighbor, weight in graph[current]:
            new_cost = cost + weight
            if new_cost < visited[neighbor]:
                visited[neighbor] = new_cost
                heapq.heappush(pq, (new_cost + heuristic(neighbor), neighbor, new_cost))

    return -1
```

