import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Heuristic function (Manhattan distance for simplicity)
    def heuristic(u, t):
        return abs(u - t)

    # A* Search
    priority_queue = [(heuristic(s, t), 0, s)]  # (estimated_total_cost, cost_so_far, node)
    visited = [False] * n
    min_cost = [float('inf')] * n
    min_cost[s] = 0

    while priority_queue:
        _, cost, u = heapq.heappop(priority_queue)

        if u == t:
            return cost

        if visited[u]:
            continue

        visited[u] = True

        for v, weight in adj[u]:
            if not visited[v]:
                new_cost = cost + weight
                if new_cost < min_cost[v]:
                    min_cost[v] = new_cost
                    heapq.heappush(priority_queue, (new_cost + heuristic(v, t), new_cost, v))

    return -1
```

