def solve(n, edges, s, t):
    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set distance to self to 0
    for i in range(n):
        dist[i][i] = 0

    # Populate the distance matrix with direct edges
    for u, v, w in edges:
