    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # Return the shortest path from s to t
    if s == t:
        return 0
    elif dist[s][t] != INF:
        return dist[s][t]
    else:
        return -1
