def solve(n, edges, s, t):
    # If source and target are the same, return 0
    if s == t:
        return 0

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # No more updates, can break early

    # Check for negative weight cycles that are reachable from s
    # If a distance can still be updated, there's a negative cycle
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            # If target is reachable via this cycle, then path is unbounded (infinite)
            # So check if target is reachable through any path
            if dist[v] != float('inf') or dist[u] != float('inf'):
                return -1  # Negative cycle detected, path is not well-defined

    # If target is unreachable
    if dist[t] == float('inf'):
        return -1

    return dist[t]
```

