import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # A* Search algorithm
    # Heuristic function: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u, t):
        return abs(u - t)

    # Priority queue: (priority, current node, current cost)
    priority_queue = [(heuristic(s, t), 0, s)]
    # Visited dictionary to keep track of the best known cost to each node
    visited = {s: 0}

    while priority_queue:
        _, cost, u = heapq.heappop(priority_queue)

        # If we reached the target
        if u == t:
            return cost

        # If we have a better path to u, skip this entry
        if cost > visited.get(u, float('inf')):
            continue

        for v, weight in adj[u]:
            new_cost = cost + weight
            # If we haven't visited v yet or found a better path
            if v not in visited or new_cost < visited[v]:
                visited[v] = new_cost
                heapq.heappush(priority_queue, (new_cost + heuristic(v, t), new_cost, v))

    # If we exit the loop and haven't returned, then t is unreachable
    return -1
```

