def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # A* search
    # Heuristic: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u, t):
        return abs(u - t)

    # Priority queue: (cost_so_far + heuristic, current_node, cost_so_far, path)
    pq = [(heuristic(s, t), s, 0)]
    visited = [False] * n
    dist = [float('inf')] * n
    dist[s] = 0

    while pq:
        _, u, cost = heapq.heappop(pq)

        if u == t:
            return cost

        if visited[u]:
            continue

        visited[u] = True

        for v, weight in adj[u]:
            if dist[v] > cost + weight:
                dist[v] = cost + weight
                heapq.heappush(pq, (dist[v] + heuristic(v, t), v, dist[v]))

    # If t is unreachable
    return -1
```

