    # If source and target are the same, return 0
    if s == t:
        return 0

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0  # Distance to source is 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        # If no updates, break early
        if not updated:
            break

    # Check for negative weight cycles that are reachable from source
    # If any distance is still INF, the node is unreachable
    if dist[t] == INF:
        return -1

    # Check for negative weight cycles that affect the target node
    # If we can still relax an edge from the target node, there is a negative cycle
    for u, v, w in edges:
        if dist[u] != INF and dist[v] > dist[u] + w:
            # If target is reachable through this edge and relaxation is possible,
            # then there is a negative cycle that affects the shortest path
            if dist[t] != INF:
                return -1  # Indicating presence of negative cycle affecting path

    return dist[t]
