import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Heuristic function: Manhattan distance (for simplicity and generality)
    def heuristic(u, t):
        return abs(u - t)

    # A* algorithm
    priority_queue = []
    heapq.heappush(priority_queue, (0 + heuristic(s, t), 0, s))  # (cost_so_far + heuristic, cost_so_far, node)

    visited = [False] * n
    dist = [float('inf')] * n
    dist[s] = 0

    while priority_queue:
        _, cost, u = heapq.heappop(priority_queue)

        if u == t:
            return cost

        if visited[u]:
            continue

        visited[u] = True

        for v, w in adj[u]:
            if not visited[v]:
                if dist[v] > cost + w:
                    dist[v] = cost + w
                    heapq.heappush(priority_queue, (dist[v] + heuristic(v, t), dist[v], v))

    return -1  # No path found
