import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # A* search algorithm
    # Heuristic: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u, t):
        return abs(u - t)

    # Priority queue: (cost_so_far + heuristic, current_node, cost_so_far, path)
    pq = [(heuristic(s, t), s, 0, [s])]
    visited = set()

    while pq:
        _, current, cost, path = heapq.heappop(pq)

        if current == t:
            return cost

        if current in visited:
            continue

        visited.add(current)

        for neighbor, weight in graph[current]:
            if neighbor not in visited:
                new_cost = cost + weight
                heapq.heappush(pq, (new_cost + heuristic(neighbor, t), neighbor, new_cost, path + [neighbor]))

    return -1
```

